```cpp
#include <iostream>
#include <fstream>
#include <vector>
#include <climits>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int N, K;
    plik >> N >> K;
    vector<int> tab(N);
    for (int i = 0; i < N; i++) plik >> tab[i];

    vector<int> kopia(tab.begin(), tab.end());
    vector<int> minima;

    for (int r = 0; r < K; r++) {
        int idxMin = 0;
        for (int i = 1; i < N; i++)
            if (kopia[i] < kopia[idxMin]) idxMin = i;
        minima.push_back(kopia[idxMin]);
        kopia[idxMin] = INT_MAX;
    }

    cout << "Kolejne minima:";
    for (int m : minima) cout << " " << m;
    cout << endl;
    cout << K << "-ty najmniejszy element: " << minima.back() << endl;
    return 0;
}
```

**Wyjasnienie**: Algorytm selekcji — K razy szukamy minimum w tablicy, za kazdym razem usuwajac znalezione minimum (ustawiajac INT_MAX). Po K iteracjach ostatnie znalezione minimum to K-ty najmniejszy element.

